859		// If this is a refresh deployment we're _always_ going to do a skip create or refresh step here for
860		// custom non-provider resources. We also need to skip refreshes for custom provider resources if they
861		// have dependencies that were skipped creates.
862		if sg.mode == refreshMode {
863			hasSkippedDeps, err := sg.hasSkippedDependencies(new)
864			if err != nil {
865				return nil, false, err
866			}
867			if (goal.Custom && !sdkproviders.IsProviderType(goal.Type)) || hasSkippedDeps {
868				// Custom resources that aren't in state just have to be skipped.
869				if old == nil {
870					sg.sames[urn] = true
871					sg.skippedCreates[urn] = true
872					return []Step{NewSkippedCreateStep(sg.deployment, event, new)}, false, nil
873				}
874				// We've already refreshed this resource, so we can just trigger the done event (refresh steps never do this
875				// alone) and return no further steps.
876				event.Done(&RegisterResult{
877					State:  event.Old(),
878					Result: ResultStateSuccess,
879				})
880				return []Step{}, false, nil
881			}
882		}
883		// If this is a destroy generation we're _always_ going to do a skip create or skip step here for custom
884		// non-provider resources. This is because we don't want to actually create any cloud resources as part of
885		// the destroy, but we do want to "create/update" providers, construct component resources and it's fine
886		// to make the relevant state edits off the back of these.
887		if sg.mode == destroyMode {
888			// We need to check if this resource is trying to depend on another resource that has already been
889			// skipped. In that case we have to skip this resource as well.
890			provider, allDeps := new.GetAllDependencies()
891			allDepURNs := make([]resource.URN, len(allDeps))
