893				allDepURNs[i] = dep.URN
894			}
895	
896			if provider != "" {
897				prov, err := sdkproviders.ParseReference(provider)
898				if err != nil {
899					return nil, false, fmt.Errorf(
900						"could not parse provider reference %s for %s: %w",
901						provider, new.URN, err)
902				}
903				allDepURNs = append(allDepURNs, prov.URN())
904			}
905	
906			for _, depURN := range allDepURNs {
907				if sg.skippedCreates[depURN] {
908					// This isn't an error (unlike when we hit this case in normal target runs), we just need to
909					// also skip this resource. Oddly we're calling NewSkippedCreateStep here even if we do have
910					// an old state, but skipped create actually behaves as a general skip just fine.
911					sg.skippedCreates[urn] = true
912					if old != nil {
913						// If this has an old state maintain the old outputs to return to the program
914						new.Outputs = old.Outputs
915					}
916					return []Step{NewSkippedCreateStep(sg.deployment, event, new)}, false, nil
