func out(snap *deploy.Snapshot, name string) string {
	for _, r := range snap.Resources {
		if r.URN.Name() == name {
			if v, ok := r.Outputs["v"]; ok {
				return v.StringValue()
			}
		}
	}
	return "<missing>"
}

func TestScratchExclude(t *testing.T) {
	t.Parallel()
	p, snap, _, _, hostF := scratchSetup(t)
	opts := lt.TestUpdateOptions{T: t, HostF: hostF, UpdateOptions: engine.UpdateOptions{
		Excludes: deploy.NewUrnTargets([]string{"urn:pulumi:test-stack::test-project::pkgA:m:typA::resB"}),
